const student = $input.first().json.body || $input.first().json;
const targetGoal = student.targetGoal || 'Full-Stack Web Developer';

// Match curated courses & internship tracks dynamically
const resourceDB = {
  'AI / ML Engineer': {
    courses: [
      { title: 'Machine Learning Specialization by Andrew Ng', platform: 'Coursera / DeepLearning.AI', url: 'https://coursera.org' },
      { title: 'PyTorch & Neural Networks Masterclass', platform: 'Udemy / YouTube FreeCodeCamp', url: 'https://youtube.com' }
    ],
    internships: [
      { title: 'Junior AI/ML Research Intern', company: 'TechAI Labs', location: 'Remote / Hybrid' },
      { title: 'Data & Computer Vision Trainee', company: 'Innovate Analytics', location: 'Bangalore / Remote' }
    ]
  },
  'Full-Stack Web Developer (Node.js & React)': {
    courses: [
      { title: 'Full Stack Open 2026 (React, Node, GraphQL)', platform: 'University of Helsinki', url: 'https://fullstackopen.com' },
      { title: 'Complete Node.js & React Developer', platform: 'Udemy / FreeCodeCamp', url: 'https://youtube.com' }
    ],
    internships: [
      { title: 'Software Engineering Intern (Frontend/Fullstack)', company: 'CloudScale SaaS', location: 'Remote' },
      { title: 'Junior Web Developer Trainee', company: 'DigitalCraft Solutions', location: 'Ahmedabad / Hybrid' }
    ]
  }
};

const defaultTrack = {
  courses: [
    { title: 'Mastering Modern Software Engineering & Cloud', platform: 'Coursera / FreeCodeCamp', url: 'https://coursera.org' },
    { title: 'System Design & Webhook Automations in n8n', platform: 'n8n Academy', url: 'https://academy.n8n.io' }
  ],
  internships: [
    { title: 'Associate Software Developer Intern', company: 'Global Tech Corp', location: 'Remote' },
    { title: 'Automation & AI Solutions Developer Intern', company: 'Apex Innovations', location: 'Hybrid' }
  ]
};

const matchedTrack = resourceDB[targetGoal] || defaultTrack;

return [{
  json: {
    ...student,
    matchedCourses: matchedTrack.courses,
    matchedInternships: matchedTrack.internships,
    matchedAt: new Date().toISOString()
  }
}];
